WITH last AS (
  SELECT SUM(value) AS users FROM (VALUES
    ("2026-07-06",84),("2026-07-07",113),("2026-07-08",80),("2026-07-09",95),("2026-07-10",84),("2026-07-11",88),("2026-07-12",87)
  ) AS t(day, value)
), prev AS (
  SELECT SUM(value) AS users FROM (VALUES
    ("2026-06-29",108),("2026-06-30",100),("2026-07-01",97),("2026-07-02",98),("2026-07-03",104),("2026-07-04",113),("2026-07-05",103)
  ) AS t(day, value)
)
SELECT last.users AS last_week_active_users, prev.users AS prev_week_active_users, (last.users - prev.users) AS change FROM last, prev;

SELECT SUM(duration_seconds)/60.0 AS total_minutes FROM (
  SELECT session_id, user_id, SUM(duration_seconds) AS duration_seconds
  FROM (
    SELECT session_id, user_id, duration_seconds FROM (
      SELECT * FROM (VALUES (1,101,300),(2,102,600)) AS t(session_id,user_id,duration_seconds)
    )
  ) GROUP BY session_id, user_id
)
